<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

class DataExportPanel
{
    public function render(string $exportUrl, string $cancelUrl, bool $requested, array $t = []): string
    {
        $backLabel = htmlspecialchars($t['backToProfile'] ?? 'Back to profile');
        $cancelUrl = htmlspecialchars($cancelUrl);

        if ($requested) {
            $title = htmlspecialchars($t['sentTitle'] ?? 'Export requested');
            $help = htmlspecialchars($t['sentHelp'] ?? 'Your data export has been requested. You will receive it by email.');

            return '<h1>' . $title . '</h1>'
                . '<p class="change-password-success">' . $help . '</p>'
                . '<div class="profile-actions">'
                . '<a class="secondary-button" href="' . $cancelUrl . '">' . $backLabel . '</a>'
                . '</div>';
        }

        $title = htmlspecialchars($t['title'] ?? 'Download my data');
        $help = $t['help'] ?? 'Request a full export of your personal data (GDPR Article 15).';
        $requestLabel = htmlspecialchars($t['request'] ?? 'Request export');
        $exportUrl = htmlspecialchars($exportUrl);

        return '<h1>' . $title . '</h1>'
            . '<p>' . $help . '</p>'
            . '<form method="POST" action="' . $exportUrl . '" class="profile-actions">'
            . '<input type="submit" class="primary-button" value="' . $requestLabel . '" />'
            . '<a class="secondary-button" href="' . $cancelUrl . '">' . $backLabel . '</a>'
            . '</form>';
    }
}
